fn solve(n: i8) -> Vec<char> {
    // We want a sequence of length n using only 'a' and 'b' (no 'c')
    // such that for every i, s[i] != s[i+2].
    //
    // Using just two characters 'a' and 'b', an alternating pattern works:
    // For example: "abababa..."
    //
    // Check:
    // s[i] != s[i+2] because s[i] and s[i+2] are the same character in a fully alternating string,
    // so we actually want them to be different.
    //
    // Wait, alternating "ababab" fails the condition because:
    // s[0] = 'a', s[2] = 'a' → same character, which violates the constraint.
    //
    // So alternating only isn't good.
    //
    // Let's try repeating "aabb":
    // s: a a b b a a b b ...
    // Check i=0: s[0]='a', s[2]='b' (different) good
    // i=1: s[1]='a', s[3]='b' (different) good
    // i=2: s[2]='b', s[4]='a' (different) good
    // i=3: s[3]='b', s[5]='a' (different) good
    //
    // This pattern "aabb" repeated satisfies the condition and uses only 'a' and 'b'.
    // So we'll build the sequence by repeating "aabb" and take first n characters.

    let pattern = ['a', 'a', 'b', 'b'];
    let mut result = Vec::with_capacity(n as usize);

    for i in 0..n {
        result.push(pattern[(i as usize) % 4]);
    }

    result
}